INSERT OR REPLACE INTO benchmark_definitions (id, name, description, type, config) VALUES (
  'tool-calling-v2',
  'Tool Calling v2',
  'Tests tool selection accuracy and argument quality across 20 prompts with smart match strategies.',
  'tool_calling',
  '{"tools":[{"name":"get_weather","description":"Get current weather for a location","parameters":{"type":"object","properties":{"location":{"type":"string","description":"City name or city, state/country"},"unit":{"type":"string","enum":["celsius","fahrenheit"]}},"required":["location"]}},{"name":"search_web","description":"Search the internet for information","parameters":{"type":"object","properties":{"query":{"type":"string","description":"Search query"}},"required":["query"]}},{"name":"send_email","description":"Send an email to a recipient","parameters":{"type":"object","properties":{"to":{"type":"string","description":"Email address of recipient"},"subject":{"type":"string","description":"Email subject line"},"body":{"type":"string","description":"Email body text"}},"required":["to","subject","body"]}},{"name":"create_calendar_event","description":"Create a calendar event","parameters":{"type":"object","properties":{"title":{"type":"string","description":"Event title"},"date":{"type":"string","description":"Event date in YYYY-MM-DD format"},"time":{"type":"string","description":"Event time in HH:MM format"}},"required":["title","date"]}}],"test_cases":[{"prompt":"What is the weather in Austin, TX?","expected_tool":"get_weather","expected_args":{"location":{"value":"Austin","match":"keywords"}}},{"prompt":"Is it going to rain in Seattle tomorrow?","expected_tool":"get_weather","expected_args":{"location":{"value":"Seattle","match":"keywords"}}},{"prompt":"What is the temperature in Tokyo right now?","expected_tool":"get_weather","expected_args":{"location":{"value":"Tokyo","match":"keywords"}}},{"prompt":"How cold is it in Reykjavik?","expected_tool":"get_weather","expected_args":{"location":{"value":"Reykjavik","match":"keywords"}}},{"prompt":"Get the weather in São Paulo in celsius","expected_tool":"get_weather","expected_args":{"location":{"value":"Paulo","match":"keywords"},"unit":{"value":"celsius","match":"exact"}}},{"prompt":"Find recent news about the EU AI Act","expected_tool":"search_web","expected_args":{"query":{"value":"EU AI Act","match":"keywords"}}},{"prompt":"Search for the best Hono.js tutorials","expected_tool":"search_web","expected_args":{"query":{"value":"Hono.js","match":"contains"}}},{"prompt":"Look up Cloudflare Workers pricing","expected_tool":"search_web","expected_args":{"query":{"value":"Cloudflare Workers pricing","match":"keywords"}}},{"prompt":"Search for how to use Effect-TS with Hono","expected_tool":"search_web","expected_args":{"query":{"value":"Effect","match":"contains"}}},{"prompt":"Find information about WebAssembly performance benchmarks","expected_tool":"search_web","expected_args":{"query":{"value":"WebAssembly","match":"contains"}}},{"prompt":"Email jordan@example.com with subject hello and body testing","expected_tool":"send_email","expected_args":{"to":{"value":"jordan@example.com","match":"exact"}}},{"prompt":"Send a meeting reminder to team@acme.com with subject Team Sync and body Do not forget our 3pm meeting","expected_tool":"send_email","expected_args":{"to":{"value":"team@acme.com","match":"exact"},"subject":{"value":"Team Sync","match":"contains"}}},{"prompt":"Notify ops@company.com that the deploy is done, subject Deploy Complete","expected_tool":"send_email","expected_args":{"to":{"value":"ops@company.com","match":"exact"},"subject":{"value":"Deploy","match":"contains"}}},{"prompt":"Send an email to ceo@startup.io about the Q4 results with a brief summary","expected_tool":"send_email","expected_args":{"to":{"value":"ceo@startup.io","match":"exact"}}},{"prompt":"Create a meeting called Team Standup on 2025-03-15","expected_tool":"create_calendar_event","expected_args":{"title":{"value":"Standup","match":"contains"},"date":{"value":"2025-03-15","match":"exact"}}},{"prompt":"Schedule a dentist appointment for 2025-04-01 at 14:30","expected_tool":"create_calendar_event","expected_args":{"title":{"value":"dentist","match":"contains"},"date":{"value":"2025-04-01","match":"exact"}}},{"prompt":"Add a calendar event: Project Review on 2025-06-10 at 09:00","expected_tool":"create_calendar_event","expected_args":{"title":{"value":"Project Review","match":"contains"},"date":{"value":"2025-06-10","match":"exact"}}},{"prompt":"What is the weather in London in fahrenheit?","expected_tool":"get_weather","expected_args":{"location":{"value":"London","match":"keywords"},"unit":{"value":"fahrenheit","match":"exact"}}},{"prompt":"Search for TypeScript 5.7 new features","expected_tool":"search_web","expected_args":{"query":{"value":"TypeScript","match":"contains"}}},{"prompt":"Email support@example.com asking about my order status, subject Order #12345","expected_tool":"send_email","expected_args":{"to":{"value":"support@example.com","match":"exact"},"subject":{"value":"12345","match":"contains"}}}]}'
);
